changeSet.sql:
-- The regulator for each nation. The ids are the Nations ids used everywhere in EPR. [Lookup].[Regulator]. CREATE TABLE fee_regulator ( id smallint NOT NULL CONSTRAINT pk_fee_regulator PRIMARY KEY, code varchar(10) NOT NULL CONSTRAINT uq_fee_regulator_code UNIQUE, description varchar(255) NOT NULL );
-- The kind of fee, for example 5 ProducerResubmission. [Lookup].[Group]. CREATE TABLE fee_group ( id integer NOT NULL CONSTRAINT pk_fee_group PRIMARY KEY, code varchar(50) NOT NULL CONSTRAINT uq_fee_group_code UNIQUE, description varchar(255) NOT NULL );
-- The variant within a group, for example 7 ReSubmitting. [Lookup].[SubGroup]. CREATE TABLE fee_sub_group ( id integer NOT NULL CONSTRAINT pk_fee_sub_group PRIMARY KEY, code varchar(50) NOT NULL CONSTRAINT uq_fee_sub_group_code UNIQUE, description varchar(255) NOT NULL );
-- A rate for one group, sub-group and regulator over a date period. [Lookup].[RegistrationFees]. -- The dates are inclusive calendar dates: the payment service compares date parts only, and its -- EffectiveTo values are 23:59:59 on the last day. CREATE TABLE fee_rate ( id integer NOT NULL CONSTRAINT pk_fee_rate PRIMARY KEY, fee_group_id integer NOT NULL CONSTRAINT fk_fee_rate_group REFERENCES fee_group (id), fee_sub_group_id integer NOT NULL CONSTRAINT fk_fee_rate_sub_group REFERENCES fee_sub_group (id), regulator_id smallint NOT NULL CONSTRAINT fk_fee_rate_regulator REFERENCES fee_regulator (id), amount numeric(19,4) NOT NULL CONSTRAINT ck_fee_rate_amount CHECK (amount >= 0), effective_from date NOT NULL, effective_to date NOT NULL, CONSTRAINT ck_fee_rate_period CHECK (effective_to >= effective_from) );
-- Overlapping periods for the same fee are caught by a test (FeesSchemaTest) for now. A database -- EXCLUDE constraint would need the btree_gist extension, which CDP doesn't enable by default. CREATE INDEX ix_fee_rate_lookup ON fee_rate (fee_group_id, fee_sub_group_id, regulator_id, effective_from);

